**1. Log estruturado (revisando e padronizando).** Uma linha de JSON com campos fixos — o módulo 8 mostrou o porquê:

```js
function linhaDeLog(level, msg, extras = {}) {
  console.log(JSON.stringify({
    level,                              // info | warn | error
    msg,
    timestamp: new Date().toISOString(),// quando (ISO, UTC)
    ...extras,                          // contexto: rota, status, traceId...
  }));
}
```

**2. Métricas manuais.** Sem biblioteca, um middleware já coleta os três números mais importantes (volume, erro, latência):

```js
const metricas = { requisicoes: 0, erros500: 0, latencias: [] };

app.use((req, res, next) => {
  const inicio = performance.now();
  metricas.requisicoes += 1;
  res.on('finish', () => {
    const latencia = performance.now() - inicio;
    metricas.latencias.push(latencia);
    if (res.statusCode >= 500) metricas.erros500 += 1;   // 5xx = o servidor quebrou
  });
  next();
});

// e uma rota que EXPÕE as métricas para a ferramenta de monitoramento buscar:
app.get('/metrics', (req, res) => {
  const latenciasOrdenadas = [...metricas.latencias].sort((a, b) => a - b);
  const p95 = latenciasOrdenadas[Math.floor(latenciasOrdenadas.length * 0.95)];
  res.json({ ...metricas, p95 }); // p95: 95% das requisições foram mais rápidas que isso
});
```

**3. Tracing — a jornada da requisição.** Um **trace id** é um código gerado quando a requisição entra, e CARREGADO em todos os logs daquela jornada — assim, com uma busca, você junta todos os passos de UM pedido:

```js
app.use((req, res, next) => {
  req.traceId = crypto.randomUUID();        // gera o id da jornada
  linhaDeLog('info', 'requisição recebida', { traceId: req.traceId, rota: req.originalUrl });
  next();
});
```

Em sistemas distribuídos, o **OpenTelemetry** padroniza esse rastreio entre serviços (o trace cruza o gateway, a API e o banco) — o conceito é o mesmo: uma jornada com um id só.

**4. Alertas — a luz de óleo.** Um alerta é uma REGRA sobre as métricas + a ação esperada:

```text
ALERTA taxa_de_erro_alta:    erros500 / requisicoes > 1% por 5 min  → investigar 5xx no log
ALERTA latencia_alta:        p95 > 500ms por 5 min                  → olhar o flame graph
ALERTA servidor_fora:        /health sem 200 por 3 min              → acionar o rollback
```

**A regra do alerta acionável:** se o alerta tocar e a pessoa não souber o que fazer, ele é barulho. Todo alerta precisa de uma primeira ação escrita (olhar o log com level=error, conferir o trace id, voltar a versão).

Um middleware só que já entrega log estruturado + métricas + trace id — cada linha com o porquê:

```js
// observabilidade.mjs
import crypto from 'node:crypto';

const metricas = { requisicoes: 0, erros500: 0, latencias: [] };

function linhaDeLog(level, msg, extras = {}) {
  console.log(JSON.stringify({
    level, msg,
    timestamp: new Date().toISOString(),
    ...extras,
  }));
}

export function observabilidade(req, res, next) {
  req.traceId = crypto.randomUUID();          // 1. id da jornada, nasce na entrada
  const inicio = performance.now();           // 2. cronômetro da latência
  metricas.requisicoes += 1;                  // 3. contador de volume

  linhaDeLog('info', 'requisição', {
    traceId: req.traceId,
    rota: req.originalUrl,
    metodo: req.method,
  });                                         // 4. log estruturado do evento

  res.on('finish', () => {
    const latencia = performance.now() - inicio;
    metricas.latencias.push(latencia);        // 5. latência registrada
    const nivel = res.statusCode >= 500 ? 'error' : res.statusCode >= 400 ? 'warn' : 'info';
    linhaDeLog(nivel, 'resposta', {
      traceId: req.traceId,
      status: res.statusCode,
      latenciaMs: Math.round(latencia * 100) / 100,
    });                                       // 6. o mesmo traceId fecha a jornada
    if (res.statusCode >= 500) metricas.erros500 += 1;
  });

  next();
}

export function rotaDeMetricas(req, res) {
  const ordenadas = [...metricas.latencias].sort((a, b) => a - b);
  const p95 = ordenadas.length
    ? ordenadas[Math.floor(ordenadas.length * 0.95)]
    : 0;
  res.json({ requisicoes: metricas.requisicoes, erros500: metricas.erros500, p95 });
}
```

**E o alerta nascendo da métrica:** o monitoramento busca `/metrics` a cada minuto e aplica as regras — `erros500 / requisicoes > 1%` dispara uma mensagem com a ação: "olhe o log com level=error — as linhas trazem o traceId para rastrear a jornada". A luz de óleo acende com a rota de investigação já escrita.

**A ordem importa:** o trace id nasce ANTES de tudo (para o primeiro log já carregá-lo); o cronômetro começa antes do trabalho e fecha no evento `finish` (que cobre a resposta inteira); o log de resposta carrega o MESMO trace id do log de entrada — é isso que transforma linhas soltas em jornada. Sem o trace id, você tem três logs; com ele, você tem UMA história.
